------------ init ------------

function TriggerGiftPanel:InitBtnBuy(giftId , expirationTime ,  numItem, iconTitle,discountOff, cb , channelProductId)

    SetButtonAction(self.BtnBuy, function()
        xRecord.record('3-024' , string.format('click_trigger_pack_buy_%d' ,checkInt(giftId)))
        if cb then cb() end
    end)
    self.giftId = checkInt(giftId)
    self.expirationTime = expirationTime
    
    local triggerGiftComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.TriggerGiftComponent)
    local giftChestData = nil
    for i, giftChest in pairs(triggerGiftComponent.triggerChest) do
        local giftId = giftChest.giftData.id
        if checkInt(self.giftId) == checkInt(giftId) then
            giftChestData = giftChest
            break
        end
    end
    if isNull(giftChestData) then
        for i, giftChest in pairs(triggerGiftComponent.cacheTriggerChest) do
            local giftId = giftChest.giftData.id
            if checkInt(self.giftId) == checkInt(giftId) then
                giftChestData = giftChest
                break
            end
        end
    end


    local isMoney = true 
    if isNotNull(giftChestData) then    
        local giftConfigData = giftChestData.configData
        local prices = giftConfigData.prices  or {}
        local count = table.count(prices)
        if count > 0 then
            isMoney = false
        end
    end
    CfUtils.FillImage(self.ImgRole , CfUtils.GetImageFullPath(giftChestData.configData.portrait))
    if isMoney then
        local payData =  CfUtils.GetPayData(numItem , channelProductId)
        CfUtils.FillText(self.TxtNumCost, string.format("<size=40>%s</size><size=58>%s</size>", payData.currencySymbol,  payData.price))        
    else 
        for goodsId, v in pairs(giftChestData.configData.prices) do
            local goodPath = GoodsConfMgr:GetInstance():GetPhotoPathById(goodsId)
            CfUtils.FillImage(self.ImgIcon.gameObject , goodPath) 
            CfUtils.FillText(self.TxtNumCost,v.current)  
            KTool.SetActive(self.ImgIcon.gameObject,true)
        end       
    end
    CfUtils.FillText(self.DiscountOffText,string.format("%d%%" ,discountOff))

    if not string.isEmpty(iconTitle) then
        KTool.SetActive(self.RemindRoot,true)
        CfUtils.FillText(self.TextDesc,iconTitle)
    else
        KTool.SetActive(self.RemindRoot,false)
    end

end
function TriggerGiftPanel:GetGiftId()
    return self.giftId
end
function TriggerGiftPanel:getExpirationTime()
    return self.expirationTime
end

function TriggerGiftPanel:InitRewardsList(data)
    local rewardEnv = CfUtils.GetLuaScr(self.CommonGoodsList,"Game.Behaviours.CommonGoodsListLight")
    if not isNull(rewardEnv) then
        rewardEnv:FreshBaseUI(data, nil, false)
    end
end

