function TriggerGiftPanel:SetTimeDownValue(seconds)
    if (not IsNull(self.TxtTime)) and seconds then
        local value = CfUtils.GetTimeHMS2(seconds) -- 返回显示格式
        CfUtils.FillText(self.TxtTime,value)
    end
end

